\end{itemize}

Region \(R\)
\[
4 x-x^{3}+1=\frac{3}{4} x \text { when } x=1.94045=A
\]
\begin{itemize}
\item[(a)]
\[
\begin{aligned}
\text { Area } & =\int_{0}^{A}\left(4 x-x^{3}+1-\frac{3}{4} x\right) d x \\
& =4.514 \text { or } 4.515
\end{aligned}
\]
\end{itemize}
\[
3\left\{\begin{array}{l}
1: \text { limits } \\
1: \text { integrand } \\
1: \text { answer }
\end{array}\right.
\]
\begin{itemize}
\item[(b)] Volume
\[
\begin{aligned}
& =\pi \int_{0}^{A}\left(\left(4 x-x^{3}+1\right)^{2}-\left(\frac{3}{4} x\right)^{2}\right) d x \\
& =18.291 \pi \text { or } 57.463
\end{aligned}
\]
\end{itemize}
\[
3\left\{\begin{array}{l}
1: \text { limits and constant } \\
1: \text { integrand } \\
1: \text { answer }
\end{array}\right.
\]
\begin{itemize}
\item[(c)]
\[
\begin{aligned}
\text { Perimeter }=1 & +\sqrt{(1.940)^{2}+(1.455)^{2}} \\
& +\int_{0}^{A} \sqrt{1+\left(4-3 x^{2}\right)^{2}} d x
\end{aligned}
\]
\end{itemize}
\[
3\left\{\begin{array}{l}
1: \text { uses } y^{\prime}=4-3 x^{2} \text { in integrand } \\
1: \text { arc length integral } \\
1: \text { answer }
